// GENERATED BY SYMPLRV3 — DO NOT EDIT
// Local passcode (team pattern): the create/confirm draft is MEMORY-ONLY
// (nav params + persisted stores leak into crash tooling); only the accepted
// passcode is stored. Verification carries the app-wide attempt budget so
// wrong entries accumulate across the design's state variants; a served
// lockout resets it. A UX guard, NOT a security control.
import React from 'react';
import { fireAndForget } from '../errors';
import AsyncStorage from '@react-native-async-storage/async-storage';

const KEY = 'app.passcode';
const ATTEMPTS_KEY = 'app.passcode.attempts';
const MAX_ATTEMPTS = 3;
const LOCK_MS = 30 * 60_000;
let draft: string | null = null;

/**
 * The failed-attempt count is PERSISTED, and the lockout EXPIRES.
 *
 * Two separate bugs met here. It used to be a module-level `let attempts = 0`
 * that was also zeroed on reaching MAX_ATTEMPTS ("the lock screen serves the
 * lockout"): killing and relaunching the app reset the counter, and so did
 * simply hitting the limit. The PIN space is 4-6 digits, so unlimited guesses
 * is the whole attack.
 *
 * Persisting it fixed that and introduced the opposite one — the count never
 * came back down, so three wrong PINs bricked the app and a reinstall was the
 * only way in. The reference stores { attempts, lockedUntil } and, once
 * lockedUntil passes, counts from zero again (passcodeVault.ts: `served`).
 * The lockout is a DELAY. That is what this record is.
 *
 * Mirrored in memory so the synchronous passcodeAttemptsLeft() keeps working;
 * AsyncStorage is the source of truth across launches.
 */
type LockRecord = { attempts: number; lockedUntil?: number };
let attempts = 0;
let lockedUntil: number | undefined;
let attemptsLoaded = false;

const NO_ATTEMPTS: LockRecord = { attempts: 0 };

/** The stored record, in either shape a build has ever written. */
function parseLockRecord(raw: string | null): LockRecord {
  if (raw == null) return NO_ATTEMPTS;
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return NO_ATTEMPTS;
  }
  if (typeof parsed === 'number') {
    // A BARE NUMBER is what older builds wrote, and JSON.parse SUCCEEDS on one
    // — so this cannot live in the catch. Read it rather than discarding the
    // count, which would hand back a full set of guesses to anyone who
    // upgraded mid-attack.
    return Number.isFinite(parsed) && parsed > 0 ? { attempts: parsed } : NO_ATTEMPTS;
  }
  const rec = parsed as LockRecord | null;
  const usable =
    rec !== null &&
    typeof rec === 'object' &&
    typeof rec.attempts === 'number' &&
    rec.attempts >= 0;
  return usable ? rec : NO_ATTEMPTS;
}

async function loadAttempts(): Promise<number> {
  if (attemptsLoaded) return attempts;
  const rec = parseLockRecord(await AsyncStorage.getItem(ATTEMPTS_KEY));
  attempts = rec.attempts;
  lockedUntil = rec.lockedUntil;
  attemptsLoaded = true;
  return attempts;
}

/** Seconds left on the lockout, 0 when not locked. */
export async function passcodeLockRemaining(): Promise<number> {
  await loadAttempts();
  if (lockedUntil === undefined) return 0;
  const remaining = lockedUntil - Date.now();
  if (remaining <= 0) return 0;
  // clamped: a device clock pushed far forward and back must not strand a user
  return Math.ceil(Math.min(remaining, LOCK_MS) / 1000);
}

async function writeLock(rec: LockRecord): Promise<void> {
  attempts = rec.attempts;
  lockedUntil = rec.lockedUntil;
  attemptsLoaded = true;
  if (rec.attempts === 0 && rec.lockedUntil === undefined) {
    await AsyncStorage.removeItem(ATTEMPTS_KEY);
  } else {
    await AsyncStorage.setItem(ATTEMPTS_KEY, JSON.stringify(rec));
  }
}

async function setAttempts(n: number): Promise<void> {
  await writeLock({ attempts: n });
}

/**
 * Why a code is refused at ENROLMENT, or null if it is acceptable.
 *
 * The design draws the rule on the create screen ("Avoid sequences/123456 or
 * repeats/111111") but nothing enforced it, so the weakest possible passcodes
 * were accepted and then sealed the refresh-token vault. Same policy as the
 * team's passcodePolicy: no run of three identical digits, no run of three
 * consecutive ascending or descending ones.
 *
 * Enrolment only — verification must never re-judge a code that is already
 * stored, or a policy change would lock people out of their own app.
 */
export type PasscodeRejection = 'length' | 'repeat' | 'sequence';

/**
 * The message the create screen shows for a refusal.
 *
 * Beside passcodeRejection on purpose: the reasons and their wording are one
 * decision, and every screen used to inline the same ternary chain to map
 * between them (Sonar S3358). `length` is the design's own PIN length, so the
 * fallback names the real digit count.
 */
export function passcodeRejectionMessage(reason: PasscodeRejection, length: number): string {
  if (reason === 'repeat') return 'Avoid repeating the same digit.';
  if (reason === 'sequence') return 'Avoid sequences like 123456.';
  return `Enter all ${length} digits.`;
}

export function passcodeRejection(code: string, length: number): PasscodeRejection | null {
  if (code.length !== length || !/^\d+$/.test(code)) return 'length';
  let repeat = 1;
  let seq = 1;
  let step = 0;
  for (let i = 1; i < code.length; i++) {
    repeat = code[i] === code[i - 1] ? repeat + 1 : 1;
    if (repeat >= 3) return 'repeat';
    const delta = Number(code[i]) - Number(code[i - 1]);
    if (delta === 1 || delta === -1) {
      seq = delta === step ? seq + 1 : 2;
      step = delta;
    } else {
      seq = 1;
      step = 0;
    }
    if (seq >= 3) return 'sequence';
  }
  return null;
}

export function setPasscodeDraft(code: string): void {
  draft = code;
}
export function getPasscodeDraft(): string | null {
  return draft;
}
/** Launch gate: passcode saved on this device → open on the pin login. */
export async function hasPasscode(): Promise<boolean> {
  return (await AsyncStorage.getItem(KEY)) != null;
}
/** Logout/reset: forget the stored passcode (next launch = normal start). */
export async function clearPasscode(): Promise<void> {
  draft = null;
  await setAttempts(0);
  await AsyncStorage.removeItem(KEY);
}
export async function savePasscode(code: string): Promise<void> {
  if (__DEV__) console.log('[SESSION] savePasscode called');
  draft = null;
  attempts = 0;
  await AsyncStorage.setItem(KEY, code);
}
/** Remaining guesses. Synchronous for render; call loadAttempts() once at
 *  mount if the very first paint must reflect a previous launch. */
export function passcodeAttemptsLeft(): number {
  return Math.max(0, MAX_ATTEMPTS - attempts);
}

/**
 * The whole passcode-entry behaviour, once, for every screen that has a keypad.
 *
 * Every such screen used to carry this ladder inline: watch the field, fire
 * when it reaches the full length, verify, clear the field, then branch on ok /
 * locked / wrong. Twenty-six lines, and identical on all of them apart from the
 * field id and where each branch goes — which are string literals, and a
 * duplication detector normalises those away. A design with a passcode screen
 * in eight states therefore shipped the same twenty-six lines eight times.
 *
 * The BRANCHES stay with the caller because that is the part the design really
 * decides; everything around them is the same everywhere and lives here.
 */
export function usePasscodeEntry(
  form: { values: Record<string, any>; setField: (k: string, v: any) => void },
  fieldId: string,
  length: number,
  arms: { onOk?: () => void; onLocked?: () => void; onWrong?: () => void },
): void {
  const value = String(form.values[fieldId] ?? '');
  // through a ref so a fresh arrow on every render does not re-run the effect
  const armsRef = React.useRef(arms);
  armsRef.current = arms;
  React.useEffect(() => {
    if (value.length !== length) return;
    fireAndForget(
      verifyPasscode(value).then((result) => {
        // cleared BEFORE the branch runs: a branch that navigates leaves this
        // screen, and a field still holding the old code would re-fire the
        // effect the moment the user came back
        form.setField(fieldId, '');
        if (result === 'ok') armsRef.current.onOk?.();
        else if (result === 'locked') armsRef.current.onLocked?.();
        else armsRef.current.onWrong?.();
      }),
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value]);
}

/** Hydrate the persisted counter (App launch / lock screen mount). */
export async function loadPasscodeAttempts(): Promise<number> {
  await loadAttempts();
  // an EXPIRED lockout is a full budget again — reporting the spent count
  // would show "0 attempts left" on a screen that will happily accept a PIN
  if (lockedUntil !== undefined && (await passcodeLockRemaining()) === 0) {
    await writeLock({ attempts: 0 });
  }
  return Math.max(0, MAX_ATTEMPTS - attempts);
}
/**
 * 'ok' resets the budget.
 *
 * With NO stored passcode this FAILS CLOSED. It used to return 'ok', reasoning
 * that a fresh install has nothing to check — but the verify screen is only
 * reached when hasPasscode() was true (see the launch gate in App.tsx), so the
 * only way to arrive here with empty storage is that the passcode was removed
 * underneath us: cleared app data, a restored backup, or an attacker wiping
 * AsyncStorage on a rooted device. In every one of those cases accepting any
 * code unlocks the app. Enrolment is reached through hasPasscode() being
 * false, never through here.
 */
export async function verifyPasscode(code: string): Promise<'ok' | 'wrong' | 'locked'> {
  const stored = await AsyncStorage.getItem(KEY);
  if (stored == null) return 'wrong';
  await loadAttempts();
  // serving a lockout — do not even compare, so a locked-out attacker cannot
  // use timing to tell a right PIN from a wrong one
  if ((await passcodeLockRemaining()) > 0) return 'locked';
  // the lockout has EXPIRED: the budget comes back, exactly as the reference
  // does (passcodeVault.ts `served`). Without this the count stays at the
  // limit for ever and the app is unusable after three typos.
  if (lockedUntil !== undefined) await writeLock({ attempts: 0 });
  if (stored === code) {
    await setAttempts(0);
    return 'ok';
  }
  const next = attempts + 1;
  if (next >= MAX_ATTEMPTS) {
    // Budget spent: start the clock. The count is KEPT alongside it — zeroing
    // here would hand an attacker MAX_ATTEMPTS fresh guesses the moment they
    // hit the limit. It is cleared when the lockout expires, not when it starts.
    await writeLock({ attempts: next, lockedUntil: Date.now() + LOCK_MS });
    return 'locked';
  }
  await writeLock({ attempts: next });
  return 'wrong';
}
